-- NUT finance schema: workbook-backed structure and initial 2026-2H snapshot.
CREATE SCHEMA "nut";

CREATE TYPE "nut"."NutBucketKind" AS ENUM ('income', 'expense', 'tax');
CREATE TYPE "nut"."NutTaxClass" AS ENUM ('non_taxable_gain', 'taxable_gain', 'tax_deductible_expense', 'non_tax_deductible_expense', 'tax');
CREATE TYPE "nut"."NutBucketLevel" AS ENUM ('major', 'middle', 'minor');
CREATE TYPE "nut"."NutLedgerType" AS ENUM ('income', 'expense');
CREATE TYPE "nut"."NutAccountingScope" AS ENUM ('project', 'team');
CREATE TYPE "nut"."NutAccountingCategory" AS ENUM ('support', 'technical');
CREATE TYPE "nut"."NutClaimStatus" AS ENUM ('review', 'approved', 'paid', 'rejected');

CREATE TABLE "nut"."finance_periods" ("id" TEXT NOT NULL, "label" TEXT NOT NULL, "period_start" DATE NOT NULL, "period_end" DATE NOT NULL, "as_of" DATE NOT NULL, "fiscal_year_label" TEXT NOT NULL, "fiscal_year_start" DATE NOT NULL, "fiscal_year_end" DATE NOT NULL, "opening_cash" BIGINT NOT NULL DEFAULT 0, "current_cash" BIGINT NOT NULL DEFAULT 0, "income_budget" BIGINT NOT NULL DEFAULT 0, "income_actual" BIGINT NOT NULL DEFAULT 0, "expense_budget" BIGINT NOT NULL DEFAULT 0, "expense_actual" BIGINT NOT NULL DEFAULT 0, CONSTRAINT "finance_periods_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."finance_buckets" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "parent_id" TEXT, "kind" "nut"."NutBucketKind" NOT NULL, "tax_class" "nut"."NutTaxClass" NOT NULL, "budget" BIGINT NOT NULL DEFAULT 0, "spent" BIGINT NOT NULL DEFAULT 0, "description" TEXT, CONSTRAINT "finance_buckets_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."budget_nodes" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "parent_id" TEXT, "level" "nut"."NutBucketLevel" NOT NULL, "kind" "nut"."NutBucketKind" NOT NULL, "tax_class" "nut"."NutTaxClass" NOT NULL, "budget" BIGINT NOT NULL DEFAULT 0, "spent" BIGINT NOT NULL DEFAULT 0, "sort_order" INTEGER NOT NULL, "formula" TEXT, "formula_key" TEXT, "note" TEXT, "active" BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT "budget_nodes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."budget_parameters" ("id" TEXT NOT NULL, "label" TEXT NOT NULL, "value" INTEGER NOT NULL, "unit" TEXT NOT NULL, "description" TEXT NOT NULL, CONSTRAINT "budget_parameters_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."monthly_flows" ("id" TEXT NOT NULL, "period_id" TEXT NOT NULL, "month" TEXT NOT NULL, "label" TEXT NOT NULL, "budget" BIGINT NOT NULL DEFAULT 0, "actual" BIGINT NOT NULL DEFAULT 0, "income" BIGINT NOT NULL DEFAULT 0, CONSTRAINT "monthly_flows_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."ledger_entries" ("id" TEXT NOT NULL, "transaction_date" DATE NOT NULL, "month" INTEGER NOT NULL, "type" "nut"."NutLedgerType" NOT NULL, "bucket" TEXT NOT NULL, "detail" TEXT NOT NULL, "income" BIGINT NOT NULL DEFAULT 0, "expense" BIGINT NOT NULL DEFAULT 0, "balance" BIGINT NOT NULL DEFAULT 0, "amount" BIGINT NOT NULL DEFAULT 0, "claimant" TEXT, "note" TEXT, "source" TEXT NOT NULL, "tax_class" "nut"."NutTaxClass" NOT NULL, CONSTRAINT "ledger_entries_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."accounting_details" ("id" TEXT NOT NULL, "scope" "nut"."NutAccountingScope" NOT NULL, "owner" TEXT NOT NULL, "category" "nut"."NutAccountingCategory" NOT NULL, "date" DATE NOT NULL, "detail" TEXT NOT NULL, "amount" BIGINT NOT NULL, "balance" BIGINT NOT NULL, "claimant" TEXT, CONSTRAINT "accounting_details_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."accounting_summaries" ("id" TEXT NOT NULL, "scope" "nut"."NutAccountingScope" NOT NULL, "name" TEXT NOT NULL, "support_budget" BIGINT NOT NULL, "support_spent" BIGINT NOT NULL, "technical_budget" BIGINT NOT NULL, "technical_spent" BIGINT NOT NULL, "entry_count" INTEGER NOT NULL, "note" TEXT, CONSTRAINT "accounting_summaries_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."claims" ("id" TEXT NOT NULL, "date" DATE NOT NULL, "detail" TEXT NOT NULL, "amount" BIGINT NOT NULL, "claimant" TEXT NOT NULL, "bucket" TEXT NOT NULL, "status" "nut"."NutClaimStatus" NOT NULL, "source" TEXT NOT NULL, "prepaid" BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT "claims_pkey" PRIMARY KEY ("id"));
CREATE TABLE "nut"."tax_summaries" ("id" TEXT NOT NULL, "period_id" TEXT NOT NULL, "taxable_gains" BIGINT NOT NULL, "non_taxable_gains" BIGINT NOT NULL, "deductible_expenses" BIGINT NOT NULL, "non_deductible_expenses" BIGINT NOT NULL, "freelance_contract_cost" BIGINT NOT NULL, "corporate_tax" BIGINT NOT NULL, "withholding_tax" BIGINT NOT NULL, "vat" BIGINT NOT NULL, "total_tax" BIGINT NOT NULL, CONSTRAINT "tax_summaries_pkey" PRIMARY KEY ("id"));

CREATE INDEX "budget_nodes_parent_sort_order_idx" ON "nut"."budget_nodes" ("parent_id", "sort_order");
CREATE INDEX "monthly_flows_period_month_idx" ON "nut"."monthly_flows" ("period_id", "month");
CREATE INDEX "ledger_entries_transaction_date_idx" ON "nut"."ledger_entries" ("transaction_date");
CREATE INDEX "ledger_entries_bucket_idx" ON "nut"."ledger_entries" ("bucket");
CREATE INDEX "accounting_details_scope_owner_date_idx" ON "nut"."accounting_details" ("scope", "owner", "date");
CREATE INDEX "accounting_summaries_scope_name_idx" ON "nut"."accounting_summaries" ("scope", "name");
CREATE INDEX "claims_status_date_idx" ON "nut"."claims" ("status", "date");
CREATE UNIQUE INDEX "tax_summaries_period_id_key" ON "nut"."tax_summaries" ("period_id");

