-- Default-deny posture for any future Supabase Data API exposure.
ALTER TABLE "nut"."finance_periods" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."finance_buckets" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."budget_nodes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."budget_parameters" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."monthly_flows" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."ledger_entries" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."accounting_details" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."accounting_summaries" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."claims" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "nut"."tax_summaries" ENABLE ROW LEVEL SECURITY;


